/* Priangan Multimedia — canonical persistence bridge
 * Repairs persistence generated by legacy save layers without changing their UI.
 * Canonical subtotal/discount values are calculated from the live quotation state
 * immediately before Supabase receives penawaran / penawaran_items / jadwal writes.
 */
(function(){
  'use strict';
  if(window.__PM_QUOTATION_SAVE_BRIDGE_CANONICAL_V1)return;
  window.__PM_QUOTATION_SAVE_BRIDGE_CANONICAL_V1=true;

  const S=v=>String(v??'').trim();
  const N=v=>{if(typeof v==='number')return Number.isFinite(v)?v:0;const s=S(v).replace(/[^0-9,.-]/g,'').replace(/\.(?=\d{3}(?:\D|$))/g,'').replace(',','.');const n=Number(s);return Number.isFinite(n)?n:0};
  const items=()=>Array.isArray(window.items)?window.items:[];
  const masters=()=>Array.isArray(window.masters)?window.masters:[];
  const days=(a,b)=>{if(!a||!b)return 1;const d=Math.round((new Date(S(b)+'T00:00:00')-new Date(S(a)+'T00:00:00'))/86400000);return d>=0?d+1:1};
  const masterFor=i=>masters().find(m=>S(m.kode)===S(i.kode))||masters().find(m=>S(m.item).toLowerCase()===S(i.item).toLowerCase())||null;
  const typeOf=i=>{const m=masterFor(i),sat=S(m?.satuan).toLowerCase().replace(/\s+/g,'');if(['unit','units','pcs','pc','buah','set'].includes(sat))return'qty';if(['m2','m²','meter2','meterpersegi','luas'].includes(sat))return'luas';const t=(S(i.item)+' '+S(m?.kategori)+' '+S(i.kode)).toLowerCase();if(/rigging|rig/.test(t))return'rigging';if(/level/.test(t))return'level';if(/led|videotron/.test(t))return'luas';return S(i.tipe||i.tipe_perhitungan)||'qty'};
  const subtotal=i=>{const p=N(i.harga??i.harga_jual),d=days(i.mulai??i.tanggal_mulai,i.selesai??i.tanggal_selesai),q=Math.max(1,N(i.qty??i.jumlah)||1),w=N(i.lebar),h=N(i.tinggi),l=N(i.panjang),t=typeOf(i);if(t==='luas')return w*h*p*d;if(t==='rigging')return((l*2)+(h*2))*p*d;if(t==='level'){const led=items().find(x=>x!==i&&/led|videotron/i.test(S(x.item)+' '+S(x.kode)));return(led?N(led.lebar):w)*p*d}return q*p*d};
  const state=()=>{const rows=items().filter(i=>i&&S(i.kode)&&S(i.item)),base=rows.reduce((s,i)=>s+subtotal(i),0),p=N(document.querySelector('#pmDiscPct')?.value),r=N(document.querySelector('#pmDisc')?.value);let discount=N(window.__pmDiscountValue);if(document.activeElement?.id==='pmDiscPct'||window.__PM_DISC_MODE==='pct')discount=Math.round(base*Math.max(0,Math.min(100,p))/100);else if(r||window.__PM_DISC_MODE==='rp')discount=Math.max(0,Math.min(base,r||discount));discount=Math.max(0,Math.min(base,discount));return{rows,base,discount,pct:base?discount/base*100:0,total:Math.max(0,base-discount)}};

  function patchClient(client){
    if(!client||client.__pmCanonicalSaveBridge)return;
    const originalFrom=client.from.bind(client);
    client.from=function(table){
      const q=originalFrom(table);if(!q)return q;
      if(table==='penawaran'){
        if(typeof q.insert==='function'&&!q.__pmCanonInsert){const oi=q.insert.bind(q);q.insert=function(values,options){const s=state();const fix=v=>({...v,subtotal:s.base,diskon:s.discount,diskon_persen:s.pct,total:s.total,grand_total:s.total});return oi(Array.isArray(values)?values.map(fix):fix(values),options)};q.__pmCanonInsert=true}
        if(typeof q.update==='function'&&!q.__pmCanonUpdate){const ou=q.update.bind(q);q.update=function(values,options){const s=state();const fix=v=>({...v,subtotal:s.base,diskon:s.discount,diskon_persen:s.pct,total:s.total,grand_total:s.total});return ou(fix(values),options)};q.__pmCanonUpdate=true}
      }
      if(table==='penawaran_items'&&typeof q.insert==='function'&&!q.__pmCanonItemInsert){const oi=q.insert.bind(q);q.insert=function(values,options){const rows=state().rows;const fix=(v,idx)=>{const src=rows[idx];return src?{...v,harga_jual:N(src.harga),harga:N(src.harga),tipe_perhitungan:typeOf(src),tipe:typeOf(src),qty:Math.max(1,N(src.qty)||1),jumlah:Math.max(1,N(src.qty)||1),lebar:N(src.lebar)||null,tinggi:N(src.tinggi)||null,panjang:N(src.panjang)||null,tanggal_mulai:S(src.mulai)||v.tanggal_mulai||null,tanggal_selesai:S(src.selesai)||v.tanggal_selesai||null,durasi:days(src.mulai||v.tanggal_mulai,src.selesai||v.tanggal_selesai),subtotal:subtotal(src)}:v};return oi(Array.isArray(values)?values.map(fix):fix(values,0),options)};q.__pmCanonItemInsert=true}
      if(table==='penawaran_jadwal'&&typeof q.insert==='function'&&!q.__pmCanonScheduleInsert){const oi=q.insert.bind(q);q.insert=function(values,options){const rows=state().rows;const fix=(v,idx)=>{const src=rows[idx];return src?{...v,qty:Math.max(1,N(src.qty)||1),tanggal_mulai:S(src.mulai)||v.tanggal_mulai||null,tanggal_selesai:S(src.selesai)||v.tanggal_selesai||null,durasi:days(src.mulai||v.tanggal_mulai,src.selesai||v.tanggal_selesai),subtotal:subtotal(src)}:v};return oi(Array.isArray(values)?values.map(fix):fix(values,0),options)};q.__pmCanonScheduleInsert=true}
      return q;
    };
    client.__pmCanonicalSaveBridge=true;
  }
  function boot(){try{if(typeof db!=='undefined'&&db)patchClient(db)}catch(_){}try{patchClient(window.db)}catch(_){}try{patchClient(window.__PM_STABLE_DB)}catch(_){}try{patchClient(window.__PRIANGAN_QUOTE_DB)}catch(_){} }
  boot();[0,50,150,300,700,1500,3000].forEach(ms=>setTimeout(boot,ms));
})();